const c = $json.promos_cache;
try{
  const p = typeof c==='string' ? JSON.parse(c) : c;
  return [{ json: { ...p, _from_cache:true } }];
}catch(e){
  return [{ json: { ok:false, hay_promos:false, mencion_saludo:'', promos:[], _from_cache:false, _parse_error:e.message } }];
}

// Lectura defensiva (.fields anidado o plano)
function F(r){ return (r && r.fields && typeof r.fields==='object') ? r.fields : (r||{}); }
function toDate(s){ if(!s) return null; const d=new Date(String(s).length<=10 ? (s+'T00:00:00-06:00') : s); return isNaN(d)?null:d; }

// Hoy a medianoche MX (-06:00)
const nowMX = new Date(Date.now() - 6*3600000);
const hoy = new Date(Date.UTC(nowMX.getUTCFullYear(), nowMX.getUTCMonth(), nowMX.getUTCDate()));

let rows=[]; try{ rows = $('Airtable · Get Promos Activas').all().map(i=>i.json).filter(r=>r && r.id); }catch(e){}

const MESES=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
function ddmmm(d){ return d ? (d.getUTCDate()+' '+MESES[d.getUTCMonth()]) : ''; }

const vig = rows.map(r=>{
  const f=F(r);
  const ini=toDate(f.fecha_inicio), fin=toDate(f.fecha_fin);
  const started = !ini || ini.getTime() <= hoy.getTime();
  const notEnded = !fin || fin.getTime() >= hoy.getTime();
  return {f, ini, fin, vigente:(f.activa===true && started && notEnded)};
}).filter(x=>x.vigente);

vig.sort((a,b)=> (Number(b.f.prioridad||0)-Number(a.f.prioridad||0)) || ((a.fin?a.fin.getTime():9e15)-(b.fin?b.fin.getTime():9e15)) );

const promos = vig.map(x=>{
  const f=x.f;
  return {
    campania: f.campania || 'Promoción',
    modelo_texto: f.modelo_texto || '',
    bono: (f.bono===''||f.bono==null)?null:Number(f.bono),
    precio_con_descuento: (f.precio_con_descuento===''||f.precio_con_descuento==null)?null:Number(f.precio_con_descuento),
    mostrar_precio_al_cliente: f.mostrar_precio_al_cliente===true,
    fecha_fin: f.fecha_fin || null,
    fecha_fin_txt: ddmmm(x.fin),
    descripcion: f.descripcion || ''
  };
});

const hay = promos.length>0;
const principal = hay ? promos[0].campania : null;
const finPrincipal = hay ? promos[0].fecha_fin_txt : null;
const modelos_en_promo = [...new Set(promos.map(p=>p.modelo_texto).filter(Boolean))];

// Mención para el saludo: SIEMPRE cualitativa, sin precios.
let mencion_saludo = '';
if(hay){
  mencion_saludo = `Estamos en plena ${principal}` + (finPrincipal?` (hasta el ${finPrincipal})`:'') +
    `, con bonos y descuentos de temporada en varios modelos` +
    (modelos_en_promo.length?` como ${modelos_en_promo.slice(0,3).join(', ')}`:'') + `.`;
}

return [{ json: {
  ok: true,
  hay_promos: hay,
  campania_principal: principal,
  fecha_fin_principal: finPrincipal,
  mencion_saludo,
  modelos_en_promo,
  promos,
  _diag: { filas_activas_leidas: rows.length, vigentes_hoy: promos.length },
  _from_cache: false
}}];
